"""Public-rate scenarios applied to current CAD; not a supplier quotation."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[2];p=R/'docs/procurement/xe-current-assembly-pad-counts.json';c=json.loads(p.read_text());n=5
panel_path=R/'docs/procurement/xe-panel-readiness.json';panel=json.loads(panel_path.read_text())
programming_path=R/'docs/procurement/xe-jlc-programming-service-review-2026-10-28.json';programming=json.loads(programming_path.read_text())
assert c['board_sha256']==hashlib.sha256((R/'hardware/xe-minimal/pendant-xe-minimal.kicad_pcb').read_bytes()).hexdigest()
assert panel['assembly_route']=='JLCPCB Standard PCBA' and panel['carrier_units_per_ordered_board']==1
assert panel['required_ordered_carriers_if_accepted']==n and panel['minimum_standard_single_or_panel_mm']==[70,70]
assert programming['service_available_for_canonical_route'] is True and programming['canonical_route']=='Standard PCBA'
rates={'double_side_setup':51.12,'double_side_stencil':16.42,'two_rigid_fixtures_for_1_to_29':16.42,'feeder_load':1.53,'smt_joint':.0016,'manual_joint':.0164,'hand_solder_order':3.58};scenarios=[]
for loads in [c['unique_mpns'],c['unique_mpn_side_pairs']]:
 items={'setup':rates['double_side_setup'],'stencil':rates['double_side_stencil'],'fixtures':rates['two_rigid_fixtures_for_1_to_29'],'feeders':loads*rates['feeder_load'],'SMT_pad_proxy':c['totals']['smd_pads']*n*rates['smt_joint'],'manual_pad_proxy':c['totals']['plated_through_pads']*n*rates['manual_joint'],'hand_solder_labor':rates['hand_solder_order']}
 scenarios.append({'assumed_feeder_loads':loads,'items_USD':items,'partial_assembly_USD':round(sum(items.values()),3)})
r={'status':'CURRENT_CAD_RATE_ARITHMETIC_NOT_JLC_QUOTE','observed_date':'2026-10-28','rate_source':'https://jlcpcb.com/help/article/pcb-assembly-price','source_update_date':'2026-10-22','board_sha256':c['board_sha256'],'pad_count_source_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'panel_readiness_sha256':hashlib.sha256(panel_path.read_bytes()).hexdigest(),'programming_service_review_sha256':hashlib.sha256(programming_path.read_bytes()).hexdigest(),'units':n,'assembly_route':'JLCPCB Standard PCBA double-sided','ordered_carriers':5,'carrier_mm':[70,70],'finished_units_per_carrier':1,'jlc_positions_per_unit':67,'currency':'USD','rates':rates,'programming_public_price_USD':programming['published_price_USD'],'programming_exact_workflow_acceptance':False,'scenarios':scenarios,'complete_assembly_USD':None,'complete_five_unit_landed_total':None,'exclusions':['Five 70x70mm bare carrier PCBs and four-via-per-unit POFV process','JLCPCB pre-shipment panel removal, edge finishing and associated inspection','All parts, sourcing, attrition and minimum purchase quantities','X-ray and other inspection, packaging, placement confirmation and applicable options','Case and cord','Programming operator hours, fixture, exact XE workflow acceptance, UID/serial capture and test records beyond the published approximate $8 engineering fee and $8/hour rate','Shipping, taxes and exchange costs','DTP401525-XE batteries'],'limits':[f"{c['unique_mpns']} MPNs and {c['unique_mpn_side_pairs']} MPN-side pairs are alternate feeder assumptions, not a quoted range",f"CAD {c['totals']['smd_pads']} SMD/{c['totals']['plated_through_pads']} PTH pads per board are proxies; supplier solder-joint classification may differ",'Setup/stencil/fixture/joint arithmetic uses public Standard double-sided rates but carrier fabrication and pre-shipment panel removal are unknown, never zero','Published programming fees are approximate and cannot be added to a complete total while operator hours and exact workflow acceptance remain unknown','Every exact MPN comes from the canonical production BOM; live stock and quotation remain unverified','Supplier assembly route, component availability and inspection are unqualified','No upload, order, payment or supplier inquiry performed']}
r['jlc_positions_per_unit']=68
(R/'docs/procurement/xe-current-assembly-cost.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(scenarios,indent=2))
